
PRAGMA foreign_keys=ON;
CREATE TABLE products(product_id TEXT PRIMARY KEY, product_name TEXT NOT NULL, category TEXT NOT NULL, unit TEXT NOT NULL, lifecycle_state TEXT NOT NULL);
CREATE TABLE suppliers(supplier_id TEXT PRIMARY KEY, supplier_name TEXT NOT NULL, region TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE machines(machine_id TEXT PRIMARY KEY, machine_name TEXT NOT NULL, machine_type TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE process_step(process_step_id TEXT PRIMARY KEY, step_name TEXT NOT NULL, sequence_no INTEGER NOT NULL UNIQUE);
CREATE TABLE bom(bom_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), material_code TEXT NOT NULL, required_qty_per_unit REAL NOT NULL CHECK(required_qty_per_unit > 0), effective_from TEXT NOT NULL, effective_to TEXT);
CREATE TABLE material_lot(material_lot_id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(supplier_id), material_code TEXT NOT NULL, received_qty INTEGER NOT NULL CHECK(received_qty > 0), received_date TEXT NOT NULL, lot_status TEXT NOT NULL, unit TEXT NOT NULL, consumed_qty REAL NOT NULL, remaining_qty REAL NOT NULL);
CREATE TABLE production_order(production_order_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), planned_qty INTEGER NOT NULL, produced_qty INTEGER NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE inspection_plan(inspection_plan_id TEXT PRIMARY KEY, process_step_id TEXT NOT NULL REFERENCES process_step(process_step_id), characteristic TEXT NOT NULL, lower_spec REAL NOT NULL, upper_spec REAL NOT NULL, unit TEXT NOT NULL);
CREATE TABLE material_consumption(consumption_id TEXT PRIMARY KEY, production_order_id TEXT NOT NULL REFERENCES production_order(production_order_id), material_lot_id TEXT NOT NULL REFERENCES material_lot(material_lot_id), material_code TEXT NOT NULL, required_qty REAL NOT NULL, consumed_qty REAL NOT NULL, unit TEXT NOT NULL);
CREATE TABLE inspection_result(inspection_result_id TEXT PRIMARY KEY, inspection_plan_id TEXT NOT NULL REFERENCES inspection_plan(inspection_plan_id), production_order_id TEXT NOT NULL REFERENCES production_order(production_order_id), process_step_id TEXT NOT NULL REFERENCES process_step(process_step_id), machine_id TEXT NOT NULL REFERENCES machines(machine_id), inspection_date TEXT NOT NULL, inspected_qty INTEGER NOT NULL CHECK(inspected_qty > 0), defect_qty INTEGER NOT NULL CHECK(defect_qty >= 0 AND defect_qty <= inspected_qty), measured_value REAL NOT NULL, result_status TEXT NOT NULL, defect_rate REAL NOT NULL);
CREATE TABLE defect(defect_id TEXT PRIMARY KEY, inspection_result_id TEXT NOT NULL REFERENCES inspection_result(inspection_result_id), production_order_id TEXT NOT NULL REFERENCES production_order(production_order_id), material_lot_id TEXT NOT NULL REFERENCES material_lot(material_lot_id), process_step_id TEXT NOT NULL REFERENCES process_step(process_step_id), machine_id TEXT NOT NULL REFERENCES machines(machine_id), defect_qty INTEGER NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL, detected_date TEXT NOT NULL);
CREATE TABLE corrective_action(corrective_action_id TEXT PRIMARY KEY, defect_id TEXT NOT NULL REFERENCES defect(defect_id), action_description TEXT NOT NULL, owner_role TEXT NOT NULL, status TEXT NOT NULL, opened_date TEXT NOT NULL, verified_date TEXT, closed_date TEXT);
